1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const LOYALTY_YEARS = 2;
66	
67	const LOYALTY_DISCOUNT = 0.2;
68	
69	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
70	
71	const BASE_PREMIUMS: Record<string, number> = {
72	  sword: 100,
73	  amulet: 60,
74	  staff: 80,
75	  potion: 40,
76	  rune: 25,
77	  moonstone: 25,
78	};
79	
80	const INSURANCE_VALUES: Record<string, number> = {
81	  sword: 1000,
82	  amulet: 600,
83	  staff: 800,
84	  potion: 400,
85	  rune: 250,
86	  moonstone: 250,
87	};
88	
89	const DEDUCTIBLE = 100;
90	
91	const CAP_MULTIPLIER = 2;
92	
93	const BLOCK_SIZE = 3;
94	
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const countsByType = (items: Item[]): Map<string, number> => {
98	  const counts = new Map<string, number>();
99	
100	  for (const item of items) {
101	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
102	  }
103	
104	  return counts;
105	};
106	
107	const typeBasePremium = (type: string, count: number): number =>
108	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
109	
110	const policyBasePremium = (items: Item[]): number =>
111	  [...countsByType(items)].reduce(
112	    (total, [type, count]) => total + typeBasePremium(type, count),
113	    0,
114	  );
115	
116	// Modifiers below all express a rate applied to some base. Keep every one of
117	// them in the form `base + base * RATE`. The algebraically equivalent
118	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
119	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
120	// upward float error rather than absorbing it.
121	
122	// Item-specific modifiers: each is computed on the affected item's OWN base
123	// premium, then summed across items. Note this is the item's UNIT base premium
124	// — never the block-adjusted one. A rune inside a block of 3 is still
125	// surcharged on its own 25 G, not on its 20 G share of the block.
126	const unitBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
127	
128	const isHighlyEnchanted = (item: Item): boolean =>
129	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
130	
131	const itemSurchargeRate = (item: Item): number =>
132	  (item.cursed ? CURSE_SURCHARGE : 0) +
133	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
134	
135	const itemSurcharges = (items: Item[]): number =>
136	  items.reduce(
137	    (total, item) => total + unitBasePremium(item) * itemSurchargeRate(item),
138	    0,
139	  );
140	
141	// Policy-wide modifiers: each is computed on the policy base premium (the sum
142	// of all item base premiums), independent of which items make it up.
143	const isLoyal = (customer: Customer): boolean =>
144	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
145	
146	const policyModifierRate = (
147	  customer: Customer,
148	  isFollowUpContract: boolean,
149	): number =>
150	  FIRST_INSURANCE_SURCHARGE -
151	  (isLoyal(customer) ? LOYALTY_DISCOUNT : 0) -
152	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
153	
154	const quote = (
155	  items: Item[],
156	  customer: Customer,
157	  isFollowUpContract: boolean,
158	): QuoteResult => {
159	  const policyBase = policyBasePremium(items);
160	  const policyModifiers =
161	    policyBase * policyModifierRate(customer, isFollowUpContract);
162	
163	  return {
164	    premium: Math.ceil(
165	      policyBase + itemSurcharges(items) + policyModifiers + PROCESSING_FEE,
166	    ),
167	  };
168	};
169	
170	interface Policy {
171	  items: Item[];
172	  remainingCap: number;
173	}
174	
175	const insuranceSum = (items: Item[]): number =>
176	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
177	
178	const openPolicy = (items: Item[]): Policy => ({
179	  items,
180	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
181	});
182	
183	const claim = (policy: Policy, incident: Incident): ClaimResult => {
184	  const payout = incident.damages.reduce(
185	    (total, damage) => total + damage.amount - DEDUCTIBLE,
186	    0,
187	  );
188	
189	  policy.remainingCap -= payout;
190	
191	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
192	};
193	
194	export const runScenario = (scenario: Scenario): ScenarioResult => {
195	  const results: StepResult[] = [];
196	  const policies = new Map<number, Policy>();
197	  let hasQuoted = false;
198	
199	  scenario.steps.forEach((step, index) => {
200	    if (step.op === "quote") {
201	      results.push(quote(step.items, scenario.customer, hasQuoted));
202	      policies.set(index, openPolicy(step.items));
203	      hasQuoted = true;
204	
205	      return;
206	    }
207	
208	    results.push(claim(policies.get(step.policy)!, step.incident));
209	  });
210	
211	  return { results };
212	};
