const claim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce(
    (total, damage) => total + damage.amount - DEDUCTIBLE,
    0,
  );

  policy.remainingCap -= payout;

  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
};

